            if Ll[m] == code: Ll[m + 1] = val; return
    setv(' 12', _f(extmax[0] / 2)); setv(' 22', _f(extmax[1] / 2)); setv(' 40', _f(1.1 * max(extmax[1], extmax[0] / 2.34)))
    for m in range(len(Ll)):
        if Ll[m] == 'Standard' and Ll[m - 1] == '  2' and Ll[m - 2] == 'AcDbTextStyleTableRecord':
            for q in range(m, m + 20):
                if Ll[q] == '  3': Ll[q + 1] = 'arial.ttf'; break
    open(path, 'wb').write('\r\n'.join(Ll).encode('cp932'))
