def save(code, ents, w, h, flags, tag=''):
    """Lưu spec tạm + file riêng + in bảng kiểm."""
    spec = geom.save_spec(os.path.join(TMP, 'spec_%s.json' % code), code, ents, w, h, flags)
    return spec


def verts_report(ents):
