        if e['t'] == 'LINE': print('L  (%.3f,%.3f)-(%.3f,%.3f)' % (*e['p1'], *e['p2']))
        elif e['t'] == 'ARC': print('A  c(%.3f,%.3f) r%.3f %.2f..%.2f' % (e['c'][0], e['c'][1], e['r'], e['a0'], e['a1']))
