import ezdxf, math
from lib import *


def ang(v): return math.degrees(math.atan2(v[1], v[0])) % 360


def extract(path, seed_line, layer=None, tol=0.02):
    """Lấy cụm LINE/ARC liên thông chứa đoạn thẳng seed_line=((x1,y1),(x2,y2)); trả (list seg có thứ tự, circles trong bbox)."""
    doc = ezdxf.readfile(path); msp = doc.modelspace()
    segs = []
    for e in msp:
        if layer and e.dxf.layer != layer: continue
        t = e.dxftype()
        if t == 'LINE':
            segs.append({'t': 'LINE', 'a': (e.dxf.start.x, e.dxf.start.y), 'b': (e.dxf.end.x, e.dxf.end.y)})
        elif t == 'ARC':
            c = e.dxf.center; r = e.dxf.radius; a0 = e.dxf.start_angle; a1 = e.dxf.end_angle
            pa = (c.x + r * math.cos(math.radians(a0)), c.y + r * math.sin(math.radians(a0)))
            pb = (c.x + r * math.cos(math.radians(a1)), c.y + r * math.sin(math.radians(a1)))
            segs.append({'t': 'ARC', 'c': (c.x, c.y), 'r': r, 'a': pa, 'b': pb, 'ccw': True, 'a0': a0, 'a1': a1})
    circles = [(e.dxf.center.x, e.dxf.center.y, e.dxf.radius) for e in msp if e.dxftype() == 'CIRCLE']
    # tìm seed
    s0 = None
    for i, s in enumerate(segs):
        if s['t'] == 'LINE' and ((math.dist(s['a'], seed_line[0]) < 0.05 and math.dist(s['b'], seed_line[1]) < 0.05) or (math.dist(s['b'], seed_line[0]) < 0.05 and math.dist(s['a'], seed_line[1]) < 0.05)):
            s0 = i; break
    assert s0 is not None, 'khong thay seed'
    comp = {s0}; changed = True
    while changed:
        changed = False
        for i, s in enumerate(segs):
            if i in comp: continue
            for j in list(comp):
                q = segs[j]
                if min(math.dist(p, r) for p in (s['a'], s['b']) for r in (q['a'], q['b'])) < tol:
                    comp.add(i); changed = True; break
    items = [segs[i] for i in comp]
    # sắp thành vòng
    chain = [items.pop(0)]
    while items:
        cur = chain[-1]['b']; ok = False
        for k, s in enumerate(items):
            if math.dist(s['a'], cur) < tol:
                chain.append(items.pop(k)); ok = True; break
            if math.dist(s['b'], cur) < tol:
                s = dict(s); s['a'], s['b'] = s['b'], s['a']
                if s['t'] == 'ARC': s['ccw'] = not s['ccw']
                chain.append(items.pop(k)); chain[-1] = s; ok = True; break
        assert ok, 'dut vong'
    assert math.dist(chain[-1]['b'], chain[0]['a']) < tol, 'khong kin'
    return chain, circles


def sample(seg, n=24):
    if seg['t'] == 'LINE': return [seg['a'], seg['b']]
    c, r = seg['c'], seg['r']
